terraform_snippet:
resource "google_compute_firewall" "allow_ssh" {
  name    = "allow-ssh-ingress"
  network = "payments-vpc"
  allow {
    protocol = "tcp"
    ports    = ["22"]
  }
  source_ranges = ["35.235.240.0/20"]
  target_tags   = ["production-backend"]
}

resource "google_container_cluster" "primary" {
  name = "payments-gke-prod"
  master_authorized_networks_config {
    cidr_blocks {
      cidr_block   = "10.128.0.0/24"
      display_name = "Corporate Bastion Subnet"
    }
  }
}

resource "google_sql_database_instance" "db" {
  name             = "customer-db-pg-prod"
  database_version = "POSTGRES_15"
  settings {
    ip_configuration {
      ipv4_enabled    = false
      private_network = google_compute_network.vpc.id
    }
  }
}

resource "google_cloud_run_service_iam_member" "member" {
  service  = google_cloud_run_service.service.name
  location = "us-central1"
  role     = "roles/run.invoker"
  member   = "serviceAccount:api-gateway-sa@payments-prod.iam.gserviceaccount.com"
}
